probe=r'''window.__allocatorLong=(saved,arm,years=4,borrowerId=-1)=>{if(!__townTest.load(saved))throw Error('Matched save rejected');const old=G.policy.fundedOfferAudit;let basePolicy={rate:G.policy.policyRate,lending:G.policy.lendingRules},startDay=G.day,startMoney=totalMoney(),startPop=G.stats.population,unpaidDays=0,byFirmDay=0;const originalIncome=fundedVacancyIncome,originalEconomy=dailyEconomy;fundedVacancyIncome=arm.startsWith('wage-only')?f=>workerIncome(f):originalIncome;dailyEconomy=function(...args){const before=new Map(G.people.map(p=>[p.id,p.unpaidDays||0]));const result=originalEconomy.apply(this,args);for(const p of G.people)if((p.unpaidDays||0)>(before.get(p.id)||0))unpaidDays+=(p.unpaidDays||0)-(before.get(p.id)||0);return result;};const treatment=arm.includes('tight')||arm.includes('recover');if(treatment){G.policy.policyRate=18;G.policy.lendingRules=90;recompute();}const rows=[];for(let d=1;d<=360*years;d++){if(arm==='funded-tight-recovery'&&d===721){G.policy.policyRate=basePolicy.rate;G.policy.lendingRules=basePolicy.lending;recompute();}__townTest.step(1);if(d%360===0){const live=G.firms.filter(f=>!f.closed),people=G.people.filter(p=>!p.deceased&&!p.movedAway),households=G.households.filter(h=>h.people.length),grocers=live.filter(f=>f.kind==='grocer'),providers=live.filter(f=>f.privateService),unpaid=G.people.filter(p=>p.job>=0&&(p.unpaidDays||0)>0).length;rows.push({year:d/360,day:G.day,population:people.length,births:G.people.filter(p=>p.id>=0&&!p.deceased&&!p.movedAway&&p.age<1).length,movedAway:G.people.filter(p=>p.movedAway).length,deaths:G.people.filter(p=>p.deceased).length,employment:G.stats.employment,employed:people.filter(p=>p.job>=0||p.publicWork).length,jobs:live.reduce((n,f)=>n+f.jobs,0),vacancies:live.reduce((n,f)=>n+Math.max(0,f.jobs-f.workers.length),0),unpaidWorkers:unpaid,unpaidWorkerDays:unpaidDays,firmClosures:G.firms.filter(f=>f.closed).length,firmCash:live.reduce((n,f)=>n+f.cash,0),treasury:G.treasury,debt:G.debt,defaults:{household:G.finance.householdDefaults||0,business:G.finance.businessDefaults||0},loans:G.loans.filter(l=>l.status==='active').length,foodNeed:G.market.foodNeed,foodCapacity:G.market.foodStaffCapacity,foodSellable:G.market.foodSellableCapacity,unmetFood:G.market.unmetFood,unmet30:G.history.slice(-30).reduce((n,x)=>n+(x.unmetFood||0),0),grocers:grocers.length,groceryWorkers:grocers.reduce((n,f)=>n+f.workers.length,0),schoolAccess:G.serviceProvision?.school?.coverage||0,fireAccess:G.serviceProvision?.fire?.coverage||0,privateProviders:providers.map(f=>({kind:f.privateService,cash:f.cash,workers:f.workers.length,profit:f.netProfit||0})),borrower:borrowerId>=0&&G.firms[borrowerId]?{kind:G.firms[borrowerId].kind,cash:G.firms[borrowerId].cash,debt:G.firms[borrowerId].debt||0,jobs:G.firms[borrowerId].jobs,workers:G.firms[borrowerId].workers.length,loan:JSON.parse(JSON.stringify(G.loans.find(l=>l.ownerType==='firm'&&l.ownerId===borrowerId)||null))}:null,treasuryEmpty:G.treasury<1,liquidityP10:households.map(h=>householdLiquidity(h)/h.people.length).sort((a,b)=>a-b)[Math.floor(households.length*.1)]||0,arrivals:G.people.filter(p=>p.arrivedDay>=startDay).length,valid:validateTown(),cashDrift:totalMoney()-startMoney,goodsError:Math.max(0,...goodsBalance().map(x=>Math.abs(x.error||0)))});}}fundedVacancyIncome=originalIncome;dailyEconomy=originalEconomy;return{arm,seed:G.worldSeed,years,policy:basePolicy,rows};};window.__prepareAllocatorCredit=seed=>{__townTest.reset('settlement',seed);__townTest.step(360);const candidates=G.firms.filter(f=>!f.closed&&f.jobs>f.workers.length).sort((a,b)=>(b.netProfit||0)-(a.netProfit||0));let loan=null,borrower=-1,decision=null;for(const f of candidates){loan=bankLoan('firm',f.id,500,720);if(loan){borrower=f.id;decision=f.creditDecision;break;}}return{saved:__townTest.save(),borrower,loan,decision};};'''
# instrument valid JS hash metadata outside page
probe=probe.replace("return{arm,seed:G.worldSeed,years,policy:basePolicy,rows,source:hashlib='not embedded'};", "return{arm,seed:G.worldSeed,years,policy:basePolicy,rows};")
seeds=[42,91,909];arms=['funded-base','wage-only','funded-tight','wage-only-tight','funded-tight-recovery'];years=4
