with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox','--disable-dev-shm-usage']);p=b.new_page();p.set_default_timeout(120000);errors=[];p.on('pageerror',lambda e:errors.append(str(e)));p.set_content(html);p.add_script_tag(content=source.replace('// SOURCE: 99-instrumentation.js',PROBE+'\n'+probe+'\n// SOURCE: 99-instrumentation.js'));p.locator('#newTown').click();p.locator('#pause').click()
 for seed in seeds:
  prep=p.evaluate('s=>__prepareAllocatorCredit(s)',seed);saved=prep['saved'];
  for arm in arms:
   r=p.evaluate('x=>__allocatorLong(x.saved,x.arm,x.years,x.borrower)',{'saved':saved,'arm':arm,'years':years,'borrower':prep['borrower']});r['foundingSeed']=seed;r['loanSetup']={k:prep[k] for k in ['borrower','loan','decision']};rows.append(r)
   for sample in r['rows']:
    if not sample['valid']['ok'] or abs(sample['cashDrift'])>.1 or sample['goodsError']>.01:raise AssertionError({'arm':arm,'seed':seed,'sample':sample})
    print(seed,arm,'y',sample['year'],'pop',sample['population'],'jobs',sample['jobs'],'employ',sample['employment'],'unpaid',sample['unpaidWorkerDays'],'food',round(sample['unmet30'],1),'debt',round(sample['debt']),flush=True)
 b.close()
assert not errors,errors
out=ROOT/'docs/evidence/food-shortage-recovery8/allocator-credit-natural-histories.json';out.write_text(json.dumps({'source_commit':__import__('subprocess').check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),'source_sha256':hashlib.sha256(source.encode()).hexdigest(),'seeds':seeds,'years':years,'arms':arms,'method':'Matched ordinary settlement saves after 360-day natural warmup, each with one API-approved $500 firm loan to a profitable vacancy-holder if approved; this funded financing is shared across arms; no grants or forced recovery. Wage-only arm uses previous effective-wage comparator in same source. Tightening uses policyRate18/lendingRules90 from intervention start; recovery arm restores original policy after2years. 360-day game years. Model evidence only.','pageErrors':errors,'runs':rows},indent=2)+'\n')
